SELECT FROM act_activity t WHERE t.deleted = 0 AND ( t.user_id = #{query.userId} OR EXISTS ( SELECT 1 FROM act_participant p WHERE p.activity_id = t.id AND p.user_id = #{query.userId} AND p.deleted = 0 ) )
AND t.status = #{query.status}
ORDER BY CASE t.status WHEN 'open' THEN 0 WHEN 'replied' THEN 0 WHEN 'completed' THEN 1 WHEN 'withdrawn' THEN 2 ELSE 3 END, t.scheduled_at DESC, t.id DESC

SELECT FROM act_activity t WHERE t.deleted = 0
AND t.status = #{query.status}
ORDER BY t.scheduled_at DESC, t.id DESC
